    if s.id == 1 {
        pass = pass + 1
    } else {
        fail = fail + 1
        println("FAIL: state id")
    }

    // Test 10: state value
    if s.value == 42 {
        pass = pass + 1
    } else {
        fail = fail + 1
        println("FAIL: state value")
    }

    // Test 11: state mem default
    if s.mem == 100 {
        pass = pass + 1
    } else {
        fail = fail + 1
        println("FAIL: state mem default")
    }

    // Test 12: converge same value
    let r1 = converge(50, 50, 0, 100, 100)
    if r1 == 50 {
        pass = pass + 1
    } else {
        fail = fail + 1
        println("FAIL: converge same")
    }

    // Test 13: converge upward
    let r2 = converge(0, 10, 0, 100, 100)
    if r2 == 10 {
        pass = pass + 1
    } else {
        fail = fail + 1
        println("FAIL: converge upward")
    }

    // Test 14: converge clamp
    let r3 = converge(90, 200, 0, 100, 50)
    if r3 == 100 {
        pass = pass + 1
    } else {
        fail = fail + 1
        println("FAIL: converge clamp")
    }

    // Test 15: resource conservation ok
    if check_resource(100, 50) {
        pass = pass + 1
    } else {
        fail = fail + 1
        println("FAIL: resource ok")
    }

    // Test 16: resource conservation fail (over)
    if check_resource(100, 150) {
        fail = fail + 1
        println("FAIL: resource over should fail")
    } else {
        pass = pass + 1
    }

    // Test 17: resource conservation fail (negative)
    if check_resource(100, -1) {
        fail = fail + 1
        println("FAIL: resource negative should fail")
    } else {
        pass = pass + 1
    }

    println("=== Solver Tests ===")
    println("PASS:")
    println(pass)
    println("FAIL:")
    println(fail)

    return fail
}

fn main() {
    let result = test_solver()
    if result == 0 {
        println("ALL SOLVER TESTS PASSED")
    } else {
        println("SOME SOLVER TESTS FAILED")
    }
}

