// FVX Pipeline — fv2 버전
// Lex → Parse → Solve → Converge 파이프라인

// ============================================================
// 결과 구조체
// ============================================================

struct PipelineResult {
    ok bool,
    steps i64,
    converged_state i64,
    node_count i64,
    error_code i64
}

fn make_ok_result(steps: i64, state: i64, nodes: i64) PipelineResult {
    return PipelineResult{ok: true, steps: steps, converged_state: state, node_count: nodes, error_code: 0}
}

fn make_err_result(code: i64) PipelineResult {
    return PipelineResult{ok: false, steps: 0, converged_state: -1, node_count: 0, error_code: code}
}

// ============================================================
// 공리 검증 (5개 FVX 공리)
// ============================================================

// A1: 상태 존재 — state_id >= 0
fn axiom_state_exists(state_id: i64) bool {
    return state_id >= 0
}

// A2: 자원 보존 — consumed <= initial
fn axiom_resource_conservation(initial: i64, consumed: i64) bool {
    return consumed >= 0 && consumed <= initial
}

// A3: 제약 완전성 — value in [lo, hi]
fn axiom_constraint_complete(value: i64, lo: i64, hi: i64) bool {
    return value >= lo && value <= hi
}

// A4: 시간 단조성 — time non-decreasing
fn axiom_time_monotone(t_prev: i64, t_next: i64) bool {
    return t_next >= t_prev
}

// A5: 관찰 가능성 — converged state observable
fn axiom_observable(converged: bool) bool {
    return converged
}

// ============================================================
// 수렴 시뮬레이션
// ============================================================

fn simulate_convergence(start: i64, lo: i64, hi: i64, max_steps: i64) PipelineResult {
    // A1 검증
    if axiom_state_exists(start) == false {
        return make_err_result(1)
    }

    let mut val = start
    let mut steps = 0
    let target = (lo + hi) / 2

    for steps in 0..max_steps {
        // A3 검증
        if axiom_constraint_complete(val, lo, hi) == false {
            if val < lo {
                val = lo
            }
            if val > hi {
                val = hi
            }
        }

        // 수렴 체크
        if val == target {
            // A5 검증
            if axiom_observable(true) {
                return make_ok_result(steps, val, steps + 1)
            }
        }

        // 한 스텝 전진
        let diff = target - val
        if diff > 0 {
            val = val + 1
        }
        if diff < 0 {
            val = val - 1
        }
    }

    return make_ok_result(max_steps, val, max_steps)
}

// ============================================================
// range_check 예제 검증
// ============================================================

fn verify_range_check() bool {
    // 0..100 범위에서 x가 절대 벗어나지 않음
    let lo: i64 = 0
    let hi: i64 = 100
    let mut x: i64 = 0
    let mut ok: bool = true

    for i in 0..100 {
        x = x + 1
        if axiom_constraint_complete(x, lo, hi) == false {
            ok = false
        }
    }

    return ok
}

// ============================================================
// pipeline 테스트
// ============================================================

fn test_pipeline() i64 {
    let mut pass: i64 = 0
    let mut fail: i64 = 0

    // Test 1: axiom_state_exists true
    if axiom_state_exists(0) {
        pass = pass + 1
    } else {
        fail = fail + 1
        println("FAIL: A1 state exists")
    }

    // Test 2: axiom_state_exists false
    if axiom_state_exists(-1) {
        fail = fail + 1
        println("FAIL: A1 negative should fail")
    } else {
        pass = pass + 1
    }

    // Test 3: axiom_resource_conservation ok
    if axiom_resource_conservation(100, 50) {
        pass = pass + 1
    } else {
        fail = fail + 1
        println("FAIL: A2 resource ok")
    }

    // Test 4: axiom_resource_conservation fail
    if axiom_resource_conservation(100, 200) {
        fail = fail + 1
        println("FAIL: A2 over should fail")
    } else {
        pass = pass + 1
    }

    // Test 5: axiom_constraint_complete ok
    if axiom_constraint_complete(50, 0, 100) {
        pass = pass + 1
    } else {
        fail = fail + 1
        println("FAIL: A3 in range")
    }

    // Test 6: axiom_constraint_complete fail
    if axiom_constraint_complete(150, 0, 100) {
        fail = fail + 1
        println("FAIL: A3 out of range should fail")
    } else {
        pass = pass + 1
    }

    // Test 7: axiom_time_monotone ok
    if axiom_time_monotone(5, 10) {
        pass = pass + 1
    } else {
        fail = fail + 1
        println("FAIL: A4 monotone ok")
    }

    // Test 8: axiom_time_monotone same
    if axiom_time_monotone(5, 5) {
        pass = pass + 1
    } else {
        fail = fail + 1
        println("FAIL: A4 same tick ok")
    }

    // Test 9: axiom_time_monotone fail
    if axiom_time_monotone(10, 5) {
        fail = fail + 1
        println("FAIL: A4 backward should fail")
    } else {
        pass = pass + 1
    }

    // Test 10: axiom_observable true
    if axiom_observable(true) {
        pass = pass + 1
    } else {
        fail = fail + 1
        println("FAIL: A5 observable")
    }

    // Test 11: axiom_observable false
    if axiom_observable(false) {
        fail = fail + 1
        println("FAIL: A5 not observable should fail")
    } else {
        pass = pass + 1
    }

    // Test 12: make_ok_result
    let r = make_ok_result(10, 50, 5)
    if r.ok {
        pass = pass + 1
    } else {
        fail = fail + 1
        println("FAIL: ok result")
    }

    // Test 13: make_err_result
    let e = make_err_result(1)
    if e.ok {
        fail = fail + 1
        println("FAIL: err result should be not ok")
    } else {
        pass = pass + 1
    }

    // Test 14: simulate_convergence basic
    let sim = simulate_convergence(0, 0, 100, 200)
    if sim.ok {
        pass = pass + 1
    } else {
        fail = fail + 1
        println("FAIL: simulate convergence")
    }

    // Test 15: verify_range_check
    if verify_range_check() {
        pass = pass + 1
    } else {
        fail = fail + 1
        println("FAIL: range check verify")
    }

    println("=== Pipeline Tests ===")
    println("PASS:")
    println(pass)
    println("FAIL:")
    println(fail)

    return fail
}

fn main() {
    let result = test_pipeline()
    if result == 0 {
        println("ALL PIPELINE TESTS PASSED")
    } else {
        println("SOME PIPELINE TESTS FAILED")
    }
}

